2.2 Спецификация асинхронного API воркера (FastAPI)
Поскольку расчет матриц связей и Conformance Checking на миллионах строк — это блокирующая CPU-bound задача, HTTP-эндпоинты работают в асинхронном режиме Task Queue с последующим опросом статуса (Long Polling).

import os
import uuid
from typing import Dict, Literal, Any
import clickhouse_connect
import pandas as pd
import pm4py
from fastapi import FastAPI, BackgroundTasks, HTTPException, status
from fastapi.responses import FileResponse
from pydantic import BaseModel, Field

app = FastAPI(title="Process Mining Heavy Analytics Engine", version="1.0.0")

# In-memory хранилище задач (в проде заменить на Redis)
tasks_registry: Dict[str, Dict[str, Any]] = {}

class GraphRequest(BaseModel):
    scenario_id: str = Field(..., example="fridge_cooking_flow")
    user_role: Literal["User", "Bot_Simulator", "QA_Automation"] = "User"
    output_format: Literal["mermaid", "bpmn"] = "mermaid"
    noise_threshold: float = Field(default=0.2, ge=0.0, le=1.0)

class TaskResponse(BaseModel):
    task_id: str
    status: Literal["PENDING", "PROCESSING", "SUCCESS", "FAILED"]
    message: str

def execute_process_mining_pipeline(task_id: str, req: GraphRequest):
    """Фоновая CPU-bound задача выгрузки, фильтрации и майнинга логов"""
    try:
        tasks_registry[task_id]["status"] = "PROCESSING"

        # 1. Подключение к кликхаусу и выгрузка плоского DataFrame
        client = clickhouse_connect.get_client(host='localhost', port=8123, username='default', password='')
        query = """
            SELECT case_id, activity_name, event_timestamp 
            FROM business_analytics.simulation_event_logs 
            WHERE scenario_id = {scen} AND user_role = {role}
            ORDER BY case_id ASC, event_timestamp ASC, activity_name ASC
        """
        df = client.query_df(query, parameters={'scen': req.scenario_id, 'role': req.user_role})

        if df.empty:
            raise ValueError(f"Event Log пуст для сценария {req.scenario_id} и роли {req.user_role}")

        # 2. Фикс параллелизма горутин и маппинг под требования PM4Py
        df = df.sort_values(by=['case_id', 'event_timestamp', 'activity_name'])
        rank = df.groupby('case_id')['event_timestamp'].rank(method='first') - 1
        df['event_timestamp'] = df['event_timestamp'] + pd.to_timedelta(rank, unit='us')

        df_log = pm4py.format_dataframe(df, case_id='case_id', activity_key='activity_name', timestamp_key='event_timestamp')

        # 3. Генерация результата в зависимости от запрошенного формата
        if req.output_format == "mermaid":
            # Используем Heuristic Miner для генерации кода графа DFG
            from pm4py.algo.discovery.heuristic import algorithm as heuristics_miner
            parameters = {heuristics_miner.Variants.CLASSIC.value.Parameters.DEPENDENCY_THRESH: 0.5}
            heu_net = heuristics_miner.apply_net(df_log, parameters=parameters)

            # Конвертируем эвристическую сеть в разметку Mermaid
            # (Здесь вызывается внутренний парсер формирования структуры 'graph TD')
            mermaid_code = "graph TD\n" + "\n".join([f"  {edge.start_node} --&gt; {edge.end_node}" for edge in heu_net.edges])

            tasks_registry[task_id].update({
                "status": "SUCCESS",
                "result_data": {"mermaid_code": mermaid_code}
            })

        elif req.output_format == "bpmn":
            # Используем Inductive Miner для построения дерева и экспорта в .bpmn
            from pm4py.algo.discovery.inductive import algorithm as inductive_miner
            from pm4py.objects.bpmn.exporter import algorithm as bpmn_exporter

            parameters = {inductive_miner.Variants.IMf.value.Parameters.NOISE_THRESHOLD: req.noise_threshold}
            process_tree = inductive_miner.apply_tree(df_log, parameters=parameters)
            bpmn_model = pm4py.convert_to_bpmn(process_tree)

            file_path = f"/tmp/process_model_{task_id}.bpmn"
            bpmn_exporter.apply(bpmn_model, file_path)

            tasks_registry[task_id].update({
                "status": "SUCCESS",
                "file_path": file_path
            })

    except Exception as e:
        tasks_registry[task_id].update({
            "status": "FAILED",
            "message": str(e)
        })

@app.post("/api/v1/analytics/build-graph", status_code=status.HTTP_202_ACCEPTED, response_model=TaskResponse)
async def start_mining_job(request: GraphRequest, background_tasks: BackgroundTasks):
    """Точка входа для бэкенда Go Core. Регистрирует задачу и переводит поток в фон."""
    task_id = f"job_{uuid.uuid4().hex[:8]}"
    tasks_registry[task_id] = {
        "status": "PENDING", "format": request.output_format,
        "result_data": None, "file_path": None, "message": ""
    }

    background_tasks.add_task(execute_process_mining_pipeline, task_id=task_id, req=request)

    return {
        "task_id": task_id, "status": "PENDING",
        "message": "Задача добавлена в очередь вычислений воркера."
    }

@app.get("/api/v1/analytics/status/{task_id}")
async def check_task_status(task_id: str):
    """Эндпоинт для Long Polling со стороны Go Core."""
    if task_id not in tasks_registry:
        raise HTTPException(status_code=404, detail="Аналитическая задача не найдена")

    task = tasks_registry[task_id]

    if task["status"] in ["PENDING", "PROCESSING"]:
        return {"task_id": task_id, "status": task["status"]}
    if task["status"] == "FAILED":
        return {"task_id": task_id, "status": "FAILED", "error": task["message"]}

    if task["status"] == "SUCCESS":
        if task["format"] == "mermaid":
            return {"task_id": task_id, "status": "SUCCESS", "type": "mermaid", "data": task["result_data"]}
        if task["format"] == "bpmn":
            return {"task_id": task_id, "status": "SUCCESS", "type": "bpmn", "download_url": f"/api/v1/analytics/download/{task_id}"}

@app.get("/api/v1/analytics/download/{task_id}")
async def download_generated_bpmn(task_id: str):
    """Отдает сгенерированный физический файл модели процесса."""
    if task_id not in tasks_registry or tasks_registry[task_id]["status"] != "SUCCESS":
        raise HTTPException(status_code=400, detail="Файл еще не готов")

    file_path = tasks_registry[task_id]["file_path"]
    if not file_path or not os.path.exists(file_path):
        raise HTTPException(status_code=404, detail="Файл стерт или отсутствует на диске воркера")

    return FileResponse(path=file_path, media_type="application/xml", filename=f"model_{task_id}.bpmn")

