        if task["format"] == "bpmn":
            return {"task_id": task_id, "status": "SUCCESS", "type": "bpmn", "download_url": f"/api/v1/analytics/download/{task_id}"}

@app.get("/api/v1/analytics/download/{task_id}")
async def download_generated_bpmn(task_id: str):
    """Отдает сгенерированный физический файл модели процесса."""
    if task_id not in tasks_registry or tasks_registry[task_id]["status"] != "SUCCESS":
        raise HTTPException(status_code=400, detail="Файл еще не готов")

    file_path = tasks_registry[task_id]["file_path"]
    if not file_path or not os.path.exists(file_path):
        raise HTTPException(status_code=404, detail="Файл стерт или отсутствует на диске воркера")

    return FileResponse(path=file_path, media_type="application/xml", filename=f"model_{task_id}.bpmn")

